import { readFile, writeFile } from 'node:fs/promises';
import YAML from 'yaml';

export type Rule = {
  id: string;
  name: string;
  metric: string;
  op: '>' | '<';
  threshold: number;
  for: string;
  severity: 'info' | 'warning' | 'critical';
};

export const RULES_PATH = 'config/alerts.yaml';

export async function loadRules(path = RULES_PATH): Promise<Rule[]> {
  const doc = YAML.parse(await readFile(path, 'utf8'));
  return doc.rules ?? [];
}

// A reload with a bad rule is rejected and the old rules stay active, so catch problems before writing.
export function validateRule(r: Rule): string | null {
  if (!r.name.trim()) return `${r.id}: name is empty`;
  if (!Number.isFinite(r.threshold)) return `${r.id}: threshold must be a number`;
  if (!['info', 'warning', 'critical'].includes(r.severity)) return `${r.id}: unknown severity ${r.severity}`;
  if (!['>', '<'].includes(r.op)) return `${r.id}: op must be > or <`;
  if (!/^\d+[smh]$/.test(r.for)) return `${r.id}: for must look like 5m or 1h`;
  return null;
}

export async function saveRules(rules: Rule[], path = RULES_PATH): Promise<void> {
  const problems = rules.map(validateRule).filter(Boolean);
  if (new Set(rules.map((r) => r.id)).size !== rules.length) problems.push('rule ids must be unique');
  if (problems.length) throw new Error(problems.join('; '));
  await writeFile(path, YAML.stringify({ rules }), 'utf8');
}

