import { mkdtemp, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { loadRules, saveRules, validateRule, type Rule } from './alerts';

const RULE: Rule = { id: 'a', name: 'A', metric: 'm', op: '>', threshold: 1, for: '1m', severity: 'info' };

async function tempPath(): Promise<string> {
  return join(await mkdtemp(join(tmpdir(), 'rules-')), 'alerts.yaml');
}

test('loads rules from YAML', async () => {
  const path = await tempPath();
  await writeFile(path, 'rules:\n  - id: a\n    name: A\n    metric: m\n    op: ">"\n    threshold: 1\n    for: 1m\n    severity: info\n');
  expect((await loadRules(path))[0].id).toBe('a');
});

test('saves rules back to YAML', async () => {
  const path = await tempPath();
  await saveRules([RULE], path);
  expect(await loadRules(path)).toEqual([RULE]);
});

test('rejects a rule whose threshold is not a number', async () => {
  expect(validateRule({ ...RULE, threshold: NaN })).toBe('a: threshold must be a number');
  await expect(saveRules([{ ...RULE, threshold: NaN }], await tempPath())).rejects.toThrow('threshold');
});

