import express from 'express';
import { listIncidents } from './incidents';
import { loadRules, saveRules } from './alerts';

const app = express();
app.use(express.json());

app.get('/api/incidents', async (_req, res) => {
  res.json(await listIncidents());
});

app.get('/api/alerts', async (_req, res) => {
  res.json(await loadRules());
});

app.put('/api/alerts', async (req, res) => {
  try {
    await saveRules(req.body);
    res.sendStatus(204);
  } catch (e) {
    res.status(400).send(e instanceof Error ? e.message : String(e));
  }
});

app.listen(4000, () => console.log('opsboard api on :4000'));

