import { replica } from './db';

export type Incident = {
  id: number;
  ruleId: string;
  title: string;
  status: 'open' | 'acknowledged' | 'resolved';
  openedAt: string;
};

export type Page = { items: Incident[]; next: string | null };

export const PAGE_SIZE = 50;

// Keyset paging on (opened_at, id): deep OFFSET pages run into the 5s statement timeout.
export function pageQuery(cursor: string | null, limit = PAGE_SIZE): { text: string; values: unknown[] } {
  const where = cursor ? 'WHERE (opened_at, id) < ($2, $3)' : '';
  const [openedAt, id] = cursor ? cursor.split('_') : [];
  return {
    text: `SELECT id, rule_id AS "ruleId", title, status,
                  to_char(opened_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS "openedAt"
             FROM incidents ${where}
            ORDER BY opened_at DESC, id DESC
            LIMIT $1`,
    values: cursor ? [limit + 1, openedAt, Number(id)] : [limit + 1],
  };
}

export async function listIncidents(cursor: string | null = null, limit = PAGE_SIZE): Promise<Page> {
  const { rows } = await replica.query(pageQuery(cursor, limit));
  const items = rows.slice(0, limit);
  const last = items[items.length - 1];
  return { items, next: rows.length > limit && last ? `${last.openedAt}_${last.id}` : null };
}

