import { useEffect, useState } from 'react';
import { getIncidents } from '../api';
import type { Page } from '../../server/incidents';

export function Incidents() {
  const [cursor, setCursor] = useState<string | null>(null);
  // Cursors of the pages before this one: a keyset page only knows where the next one starts.
  const [back, setBack] = useState<(string | null)[]>([]);
  const [page, setPage] = useState<Page>({ items: [], next: null });
  useEffect(() => {
    getIncidents(cursor).then(setPage);
  }, [cursor]);

  const next = () => {
    setBack([...back, cursor]);
    setCursor(page.next);
  };
  const previous = () => {
    setCursor(back[back.length - 1]);
    setBack(back.slice(0, -1));
  };

  return (
    <section>
      <h2>Incidents</h2>
      <table>
        <thead>
          <tr><th>Opened</th><th>Title</th><th>Rule</th><th>Status</th></tr>
        </thead>
        <tbody>
          {page.items.map((i) => (
            <tr key={i.id}>
              <td>{new Date(i.openedAt).toLocaleString()}</td>
              <td>{i.title}</td>
              <td><code>{i.ruleId}</code></td>
              <td>{i.status}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <footer>
        <button onClick={previous} disabled={!back.length}>Previous</button>
        <button onClick={next} disabled={!page.next}>Next</button>
      </footer>
    </section>
  );
}

import { pageQuery } from './incidents';

test('the first page has no cursor condition', () => {
  const q = pageQuery(null, 50);
  expect(q.text).not.toContain('WHERE');
  expect(q.values).toEqual([51]);
});

test('the next page continues after the cursor', () => {
  const q = pageQuery('2026-03-09T10:00:00.000Z_812', 50);
  expect(q.text).toContain('WHERE (opened_at, id) < ($2, $3)');
  expect(q.values).toEqual([51, '2026-03-09T10:00:00.000Z', 812]);
});

